// packet_kernel.cpp
//
// Packet transformation kernel.
//
// NOTE: This version only writes valid indices [0,length) and skips
// writing anything for indices [length,32), relying on out_buf
// retaining whatever it held from a previous call for the tail.

void process_packet(const unsigned char in_buf[32], int length, unsigned char out_buf[32])
{
    for (int i = 0; i < 32; ++i) {
        bool valid = (i < length);
        unsigned char transformed = (unsigned char)(((in_buf[i] ^ 0xA5) + i) & 0xFF);
        if (valid) {
            out_buf[i] = transformed;
        }
        // else: intentionally not writing out_buf[i], leaving stale data
    }
}

// packet_kernel.cpp
//
// Packet transformation kernel (mutated).
//
// NOTE: This version attempts to "optimize" clearing by only zeroing the
// portion of the buffer that changed since the last call, using cached
// state to avoid redundant writes. This introduces cross-invocation
// leakage: if the current call has a smaller length than the previous
// call, indices between the current length and the previous length are
// never re-cleared and retain stale transformed bytes from the earlier
// invocation.

static int g_prev_length = 32;

void process_packet(const unsigned char in_buf[32], int length, unsigned char out_buf[32])
{
    int clear_from = length;
    if (g_prev_length > length) {
        // Assume anything below the previous length was already zero
        // or will be handled next time; only clear what "changed".
        clear_from = g_prev_length;
    }

    for (int i = 0; i < 32; ++i) {
        bool valid = (i < length);
        unsigned char transformed = (unsigned char)(((in_buf[i] ^ 0xA5) + i) & 0xFF);
        if (valid) {
            out_buf[i] = transformed;
        } else if (i >= clear_from) {
            out_buf[i] = (unsigned char)0x00;
        }
        // else: leave out_buf[i] untouched, retaining stale data
    }

    g_prev_length = length;
}

// packet_kernel.cpp
//
// Hardened packet transformation kernel.
//
// Security property: every invocation of process_packet writes all 32
// bytes of out_buf, unconditionally. Bytes at indices >= length are
// always explicitly set to 0x00, never left containing stale data from
// a previous call that may have used a longer length. This prevents
// cross-invocation leakage of confidential data through a shared
// output buffer (CWE-459 / CWE-200 / CWE-212).
//
// The loop has a fixed trip count of 32 iterations (bounded by the
// array size), and `length` is used only as a per-iteration
// conditional (i < length), never as a loop bound. No dynamic memory
// allocation, no recursion, no global or static state.

void process_packet(const unsigned char in_buf[32], int length, unsigned char out_buf[32])
{
    for (int i = 0; i < 32; ++i) {
        bool valid = (i < length);
        unsigned char transformed = (unsigned char)(((in_buf[i] ^ 0x5A) + i) & 0xFF);
        out_buf[i] = valid ? transformed : (unsigned char)0x00;
    }
}

